-- Angel Studios, Inc. (angel-studios)
-- Last verified: 2026-09-23T00:00:00+00:00
-- ============================================================

INSERT INTO research_companies (slug, legal_name, jurisdiction, operational_hq, primary_archetype, self_described_archetype, reporting_standard, functional_currency, presentation_currency, financial_year_end, tier, expected_disclosure_cadence, market_cap_band, funding_source, acn, abn, arbn, isin, lei, curator_notes, last_verified_at, is_published)
SELECT
  'angel-studios',
  'Angel Studios, Inc.',
  'US',
  NULL,
  'treasury_allocation',
  'treasury_allocation',
  'us_gaap',
  'USD',
  'USD',
  '12-31',
  'peer_shaped',
  'quarterly',
  NULL,
  'mixed',
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  $q$The record that should settle the source-ladder argument.

Angel Studios discloses its bitcoin more precisely than any other company in this register. Its quarterly reports give the holding to one decimal place (303.1 BTC), the cost basis to the dollar ($19,617,187), the carrying value at each reporting date, the accounting standard and adoption date (ASU 2023-08 from 1 January 2025), the fair value hierarchy level, the named principal market, the cost-flow method (first in, first out), and an explicit statement about custody. Every one of those facts is refused. They all arrive in a 10-K or a 10-Q, and the ladder puts audited accounts at rank 3 against the rank 2 that custody, accounting treatment and ledger events require. Panther Metals, whose entire confirmed holding is one bitcoin, has its custody arrangements stored because they appeared in an RNS. This register can tell a client who holds Panther's single coin and not who holds Angel's three hundred.

So this record carries identity and nothing else. Not because the disclosure is poor — because it is good, and arrives in the wrong envelope.

What the refused disclosure says, with its provenance, in case the ladder decision goes the other way. Holding 303.1 BTC at 30 June 2026, unchanged at every reporting date since 31 March 2025; cost basis $19,617,187; carrying value $17,747,262 at 30 June 2026, against $20,682,504 at 31 March 2026, $26,527,560 at 31 December 2025 and $34,545,487 at 30 September 2025. Carrying value is now below cost, so the position is under water on the company's own numbers. Bitcoin is treated as an indefinite-lived intangible measured at fair value through net income since adopting ASU 2023-08 on 1 January 2025; before that, cost less impairment. No purchases and no dispositions in any quarter of 2026.

Two details worth the decision on their own. First, the principal market changed: the September 2025 quarterly names Coinbase as the active exchange determined to be the principal market for bitcoin; the 2026 quarterlies name BitGo. The principal-market determination drives the fair value number, so this is a measurement judgement that moved between reporting dates, disclosed in passing and never flagged as a change. That is exactly the sort of thing the register exists to catch, and it sits in the class of document the gate refuses. Second, the custody language is the vaguest of any record here: the company has ownership and control of its digital assets and "may use" third-party custodial services. Compare Panther, which names its provider and its consultancy. Precise on quantity, vague on custody — and the vague version is also the one that cannot be stored.

Context from secondary sources, not stored and not verified here: the company reports negative stockholders' equity and roughly $100m of notes payable with a coupon above 13%, alongside the bitcoin holding. If that holds up against the filings, it belongs in the same conversation as Locate's lender covenant, Hamak's sale to fund drilling and Panther's collateral pledge — the question of what ranks ahead of the treasury.

Restricted, and worth naming because trackers publish it prominently: mNAV figures above ten circulate for this company. Not stored, not repeated to a client.

Gaps: operational headquarters not taken (reported as Provo, Utah by trackers only); the 2021 and 2024 acquisition history exists but no primary source for it has been registered; whether any 8-K carries the holdings figure in filed rather than furnished form has not been checked, and that is the one route by which this record could gain a ledger under the current rules.$q$,
  '2026-09-23T00:00:00+00:00',
  FALSE
WHERE NOT EXISTS (SELECT 1 FROM research_companies WHERE slug = 'angel-studios');

