-- Last verified: 2026-09-23T00:00:00+00:00
-- ============================================================

INSERT INTO research_companies (slug, legal_name, jurisdiction, operational_hq, primary_archetype, self_described_archetype, reporting_standard, functional_currency, presentation_currency, financial_year_end, tier, expected_disclosure_cadence, market_cap_band, funding_source, acn, abn, arbn, isin, lei, curator_notes, last_verified_at, is_published)
SELECT
  'goodfood-market',
  'Goodfood Market Corp.',
  'CA',
  'Montréal, Québec',
  'treasury_allocation',
  'treasury_allocation',
  'ifrs',
  'CAD',
  'CAD',
  'week-based 52/53-week calendar (Q3 FY2026 ended 6 June 2026)',
  'peer_shaped',
  'quarterly',
  NULL,
  'operating_cash',
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  $q$The first record where the bitcoin is not bitcoin. Goodfood announced in January 2025 that it had completed an initial investment of about $1m through a spot bitcoin ETF, with a stated intention to add from future excess cash flows. It holds fund units, not coins, and has never — in anything sighted — stated a bitcoin quantity.

The trackers state one anyway: 25 BTC, stamped June 2025, with no cost basis. That number is somebody's look-through of an ETF position into an implied coin count. It is the DigitalX pathology in its purest form, and it is the reason holding_bases exists. Nothing is stored: no snapshot, no event, no quantity, because the only quantity in circulation is derived by a third party from a position the company describes in dollars.

For an Australian CFO this is the most immediately useful record in the register, because the ETF route is the one most mid-market boards will actually be offered. The trade-offs are real and mostly favourable at this size: no custody to arrange, no key management, no private-key risk, a familiar instrument the auditor already understands, and — the part that matters most — a completely different accounting treatment. Direct bitcoin lands in intangibles under IAS 38 or AASB 138 with its impairment mechanics; an ETF unit is a financial instrument. Four of the seven accounting treatments this register has catalogued simply do not arise. What you give up is direct ownership, the fee drag, and the ability to say you hold bitcoin — which, judging by the register, is often the actual motive.

A fourth distinct reason for an empty record, and the one that matters for the ingest build. DigitalX and Block are empty for want of a basis. Angel Studios and Rumble for want of a document class. Panther and 333D for want of a located primary. Goodfood is empty because its primary filings live on SEDAR+, which is not fetchable the way EDGAR and the RNS feed are. The press release reaches this record through the company's own investor page at rank 5, which carries identity and nothing gated. A Canadian record cannot be ingested until there is a SEDAR+ adapter; that is a build item, not a research failure.

How the story is going, and why it belongs on the page. On 23 July 2026 the company announced a review of the strategic alternatives available to it in order to stabilise its financial position and debt levels, following its third-quarter results. Eighteen months from adopting a treasury reserve asset to a balance-sheet stabilisation review. Nothing sighted says the bitcoin position caused that, and on a $1m position against a business this size it plainly did not. The instructive part is the sequence: Hamak sold bitcoin to fund drilling, Vaultz voted to unwind its policy entirely, and here a treasury policy adopted with confidence sits inside a company now reviewing its options. A treasury reserve is only a reserve while the business behind it is solvent.

Schema note: the fiscal calendar is week-based — thirteen and thirty-nine week periods, the third quarter ending 6 June 2026 — so there is no fixed year-end date. financial_year_end is a text field and now contains a sentence rather than a date, which anything parsing it will not enjoy. Retail and food companies commonly report this way, so it will recur.

Gaps: whether the ETF position is still held, and at what value, as at the most recent quarter; the accounting classification the company actually applies; any purchases after the initial investment; and the primary filings, all of which are on SEDAR+.$q$,
  '2026-09-23T00:00:00+00:00',
  FALSE
WHERE NOT EXISTS (SELECT 1 FROM research_companies WHERE slug = 'goodfood-market');

