-- Hamak Strategy Limited (hamak-strategy)
-- Last verified: 2026-09-23T00:00:00+00:00
-- ============================================================

INSERT INTO research_companies (slug, legal_name, jurisdiction, operational_hq, primary_archetype, self_described_archetype, reporting_standard, functional_currency, presentation_currency, financial_year_end, tier, expected_disclosure_cadence, market_cap_band, funding_source, acn, abn, arbn, isin, lei, curator_notes, last_verified_at, is_published)
SELECT
  'hamak-strategy',
  'Hamak Strategy Limited',
  'unknown',
  NULL,
  'treasury_allocation',
  'treasury_allocation',
  'ifrs',
  NULL,
  NULL,
  '12-31',
  'peer_shaped',
  'episodic',
  NULL,
  'mixed',
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  $q$Asked for as "Hamak Gold". That was the name until the 2025 repositioning, and the London RNS feed still files the company under the old one — the announcement of last Friday's bitcoin sale sits at a URL reading "hamak-gold-limited-npv-di---hama". The register's seventh identifier lesson, and the first where the exchange's own feed carries the stale name.

Why this record matters: on 18 September 2026 Hamak sold 8 of its 26 bitcoin for £482,516 to pay for a Preliminary Economic Assessment at a gold project in Ghana, retire debt and fund working capital. Not to pay a dividend, not to buy back stock, not to rebalance a treasury — to fund the operating business the treasury was meant to support. That is the scenario an Australian mid-market CFO should see before adopting a policy: the holding is real capital, and when the project needs money the holding is what is there to sell. The company frames it as tactical and says the long-term commitment to gold and bitcoin is unchanged, which may well be true and is also what every first sale sounds like. Strategy did the same thing in the same quarter at four hundred thousand times the size, for dividends rather than drilling.

Second reason: the register's first look-through exposure sitting alongside a direct holding. Hamak holds 6,500,000 shares, about 3.05%, of Vaultz Capital plc (AQSE: V3TC), a listed company whose asset base was substantially bitcoin. The economic position is 18 BTC direct plus a slice of someone else's 134. No look-through quantity is stored: that arithmetic is mine, not the company's, and the look_through basis is non-comparable precisely so it cannot leak into an aggregate. DigitalX's problem in a new shape.

The part worth watching: in July 2026 Vaultz convened a meeting to withdraw its own bitcoin treasury policy and seek authority to dispose of its holdings, and Hamak said it would vote in favour, reasoning that realising the bitcoin would let Vaultz reposition as a cash-backed acquisition platform. A bitcoin treasury company unwinding, with a fellow holder voting for it. The register now holds the entry decision, an exchange's challenge to one, a sale to fund operations, and a peer's exit.

A third accounting treatment refused, and the pattern is now unarguable. FY2025 results describe bitcoin carried as an intangible asset at cost of about $2.366m, which under UK-adopted IFRS means IAS 38 with impairment — a different answer again from Locate's AASB 138 revaluation, Block's ASC 350-60 fair value and Metaplanet's Japanese GAAP remeasurement. It cannot be stored: annual accounts are rank 3 against the rank 2 the field requires, and the version sighted here came through a republisher in any case. Three records blocked on accounting treatment, four distinct standards across seven companies, and the one field that would let a CFO compare them is the field the gate refuses.

Identity is deliberately incomplete, and the schema would not let it be. Jurisdiction is recorded as "unknown" because the column is NOT NULL and nothing sighted states where the company is incorporated: the London listing is in depositary-interest form ("NPV DI"), which usually means a non-UK issuer. UK-listed is not UK-incorporated, and this register resolves on registration rather than on where shares trade. A NOT NULL jurisdiction forces either a guess or a sentinel, and a sentinel that looks like a country code will eventually be read as one. Currencies are null for a related reason: results reported in US dollars, capital raised in sterling, the bitcoin sale priced in sterling with a dollar equivalent in brackets — three currencies in one small company and no sighted statement of the functional one. reporting_standard is ifrs because UK Main Market issuers report under UK-adopted IFRS, not because a sighted document says so.

Gaps: no custody disclosure; no primary source for the 2025 acquisitions, so the opening 20 BTC and the increase to 26 are absent from the ledger and the snapshot series starts at 18; the physical gold holding (1.65kg, early 2026) is recorded nowhere, because the schema has no non-bitcoin treasury asset — a modelling question rather than an omission; the Vaultz meeting outcome is unchecked.$q$,
  '2026-09-23T00:00:00+00:00',
  FALSE
WHERE NOT EXISTS (SELECT 1 FROM research_companies WHERE slug = 'hamak-strategy');

