-- ============================================================
-- Sequans Communications S.A. (sequans)
-- Last verified: 2026-09-28T00:00:00+00:00
-- ============================================================

INSERT INTO research_companies (slug, legal_name, jurisdiction, operational_hq, primary_archetype, self_described_archetype, reporting_standard, functional_currency, presentation_currency, financial_year_end, tier, expected_disclosure_cadence, market_cap_band, funding_source, acn, abn, arbn, isin, lei, curator_notes, last_verified_at, is_published)
SELECT
  'sequans',
  'Sequans Communications S.A.',
  'FR',
  'France',
  'treasury_company',
  'treasury_company',
  'ifrs',
  NULL,
  NULL,
  '12-31',
  'bellwether',
  'quarterly',
  NULL,
  'mixed',
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  $q$The first company in the register to hold none. On 24 September 2026 Sequans announced it had sold the remaining 314 bitcoin held on its balance sheet at 30 June 2026, completing an exit that began with the redemption of its convertible debt in May 2026. Fifteen months earlier it had raised roughly $384m and stated an intention to hold 100,000 bitcoin by 2030. It now holds zero.

Every other record answers "what does it hold". This one answers "what happened when it stopped", and it is the most complete arc available: adoption, accumulation, a collateral pledge, forced-looking sales into a falling price, debt redemption, and a full unwind, all inside two years. Hamak sold a third of its holding to fund drilling; Vaultz voted to unwind; Goodfood went into a strategic review. Sequans is the finished version of that story, and the CEO's framing — monetising the remaining holdings in a measured and opportunistic manner, emerging with a strengthened balance sheet — is the language a board uses when the treasury has become the thing being managed rather than the thing doing the protecting.

Live source conflict, caught on the day. Wire coverage of this announcement splits between 314 BTC and 34 BTC for the final sale, and at least one aggregator is publishing both figures side by side with a note that sources disagree. The primary says 314, twice, unambiguously. This is the single best demonstration the register has produced of why it exists: the correct number was freely available in a filing while the secondary layer argued with itself. Worth keeping as the canonical example for the secondary_claims proposal.

What the announcement does not say is as instructive as what it does. No sale date. No price. No proceeds. An exit of this significance is disclosed as a completed fact with no consideration attached, which is why the disposal event here carries a quantity and nothing else. For comparison, Strategy disclosed each weekly sale to the dollar and Hamak gave a per-coin price.

A filing regime the register has not met, and the spec does not cover. Sequans is a foreign private issuer: it files an annual report on Form 20-F and furnishes everything else on Form 6-K. There is no filed 8-K equivalent and no RNS. The 6-K is the entire continuous-disclosure channel, so the convention I applied to Strategy — never source a gated row to a furnished press-release exhibit — would empty this record completely, for a company whose disclosure is perfectly adequate. I have provisionally treated the 6-K as an exchange announcement at rank 2 and everything stored here depends on that call. Decision 2 in the schema spec lists ASX, TDnet, RNS, SEDAR+ and SEC domestic forms; it needs a row for the FPI regime, and the furnished-versus-filed rule needs an explicit carve-out where furnishing is the only channel available.

Refused, and material: 970 BTC sold in November 2025 taking debt from $189m to $94.5m; 1,025 BTC sold in Q1 2026 as holdings fell from 2,139 to 1,114 by 30 April; 817 of those remaining pledged as collateral against $35.9m of convertible debt; 1,167 BTC sold across the first half of 2026 for $80.1m against an original cost producing a realised loss of $56.8m; proceeds directed to debt redemption and an American depositary share buyback. All of that reaches this record through trade press citing regulatory filings rather than the filings themselves. The 20-F and the half-year 6-K will carry it; neither has been retrieved.

The collateral pledge deserves its own line, because Panther Metals only proposed one. Sequans actually did it, and the consequence is visible in the sequence: bitcoin pledged against convertible debt, then sold into weakness to redeem that debt. An encumbered holding is not a reserve — it is the creditor's collateral that happens to sit on your balance sheet. The encumbrance columns proposed in the spec would have made this legible a year before the exit.

Schema gap this record creates: there is no way to say a company has exited. primary_archetype still reads treasury_company, which is what it was, and the zero snapshot is the only signal that it is not one now. A register of holders needs a holding_status — active, exited, never_held — or every consumer must infer present tense from a snapshot series. Related: the trackers will now either drop this company or keep showing a stale figure forever, and the register should be able to say "exited on 24 September 2026" rather than falling silent.

Identity and accounting: a French société anonyme with ADSs on the NYSE, so ordinary shares and depositary shares are different instruments with different counts — any per-share metric must state which, and the buyback was of ADSs. Reporting standard is recorded as ifrs on the basis that it files a 20-F as a French issuer; no sighted document states the basis, and currencies are left null for the same reason. FY2025 results were reported as showing a record loss driven by bitcoin, described in secondary coverage as impairment, which would place this alongside Hamak under IAS 38 rather than under a fair value model — unconfirmed, and it matters, because the realised loss on exit depends on it.

Gaps: the 20-F for FY2025; the May 2026 debt redemption 6-K; the November 2025 and Q1 2026 sale disclosures; the July 2025 announcement of the 100,000 BTC target and the capital raise behind it; the sale price and proceeds of the final 314, which may never be disclosed.$q$,
  '2026-09-28T00:00:00+00:00',
  FALSE
WHERE NOT EXISTS (SELECT 1 FROM research_companies WHERE slug = 'sequans');

