-- ============================================================
-- Strategy Inc (strategy)
-- Last verified: 2026-09-21T00:00:00+00:00
-- ============================================================

INSERT INTO research_companies (slug, legal_name, jurisdiction, operational_hq, primary_archetype, self_described_archetype, reporting_standard, functional_currency, presentation_currency, financial_year_end, tier, expected_disclosure_cadence, market_cap_band, funding_source, acn, abn, arbn, isin, lei, curator_notes, last_verified_at, is_published)
SELECT
  'strategy',
  'Strategy Inc',
  'US',
  'Tysons Corner, Virginia',
  'treasury_company',
  'treasury_company',
  'us_gaap',
  'USD',
  'USD',
  '12-31',
  'bellwether',
  'monthly',
  NULL,
  'mixed',
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  $q$Read for mechanism, never for scale. At 845,050 BTC this record is roughly five orders of magnitude from anything a mid-market Australian balance sheet will do, and the register's value here is the governance machinery, not the position.

The most transferable artefact on the page is the Digital Credit Capital Framework of 29 June 2026: a board-approved USD Reserve policy with a hard floor of twelve months of preferred dividends and interest, a closed list of uses, and a BTC Monetization Program that enumerates exactly three purposes for which bitcoin may be sold — anything else needs fresh board authorisation. It is the same shape as the liquidity covenant Locate's lender imposed on it, except here the board imposed it on itself. Read the two records side by side.

Holdings trap, and the fourth distinct one across four records: a holdings-only watcher reads mid-2026 as flat — 847,363 BTC at 28 June, 845,050 at 13 September. In between the company sold 6,916 BTC across four weekly periods under the monetization program, then bought 4,603 back. The flow reversed direction twice while the stock figure barely moved. Snapshots alone would have missed the most significant policy change in six years. Two running totals also fail to reconcile by one bitcoin each (843,775 less 1,638 is 842,137, filed as 842,138; 842,138 less 1,690 is 840,448, filed as 840,447) — the filings say "approximately", and the 30 June figure of 846,000 is suspiciously round. From 6 July 2026 figures are cut at 4:00 p.m. Eastern on the last day of the period; earlier weeks carry no stated cut-off.

Source-class trap, and the one that needs a decision: the source ladder is ASX-shaped and US filings do not fit it. A single 8-K carries both filed content (Item 8.01, Exchange Act s18 liability) and furnished content (Items 7.01 and 2.02, expressly not filed) — the earnings release exhibits are furnished. This record classes 8-K bodies as exchange_announcement and sources every ledger row to an Item 8.01 body, never to an Exhibit 99.1. The 10-K is classed audited_accounts at rank 3 per the Block precedent, even though its custody section sits in Item 1, which is not audited at all. Refused by the source gate as a result, both from the FY2025 10-K: custody — Coinbase Custody Trust Company 287,322 BTC (40%), Anchorage Digital Bank 262,194 (37%), Fidelity Digital Assets 167,615 (23%) at 13 February 2026, no sub-custodians, no related-party custodians; and accounting treatment — ASU 2023-08 adopted 1 January 2025, fair value through net income, US$12.75bn cumulative-effect adjustment to opening retained earnings, US$4.06bn of cumulative impairment under the prior intangible model. That is the second US record where custody or accounting cannot be stored. Two records is a pattern; this is now a schema decision, not a footnote. The Q2 2026 10-Q has no honest source class at all — it is filed and reviewed but unaudited — and is not registered.

Identifier trap: renamed from MicroStrategy Incorporated; six quoted securities (MSTR, STRF, STRC, STRK, STRD on Nasdaq, STRE on the Luxembourg exchange). The only stable key across the whole history is SEC CIK 1050446, and research_companies has no column for it.

Date trap: the 6 July 2026 8-K is signed "June 29, 2026" in its signature block; the date of earliest event reported is 29 June. The filing date is not the signature date.

Cadence: the company files weekly, on Mondays. The cadence vocabulary stops at monthly, so freshness monitoring on this record runs four times too slow.

Also a lead, not a fact: a 32 BTC sale in the week to 31 May 2026, reported by secondary sources only. The primary 8-K has not been sighted.$q$,
  '2026-09-21T00:00:00+00:00',
  FALSE
WHERE NOT EXISTS (SELECT 1 FROM research_companies WHERE slug = 'strategy');

