INSERT INTO treasury_events (company_id, event_type, asset_class, event_date, quantity, consideration_native, native_currency, fees_included, headline, detail, disclosure_venue, filing_entity, basis, natural_key, source_document_id)
SELECT
  (SELECT id FROM research_companies WHERE slug = 'strategy'),
  'policy_adoption',
  'btc',
  '2026-06-29',
  NULL,
  NULL,
  NULL,
  NULL,
  'Digital Credit Capital Framework adopted',
  'Five components. (1) USD Reserve policy, board-approved: usable only for preferred dividends and interest; any other use, or any reduction below a floor of twelve months of expected dividends and interest, needs board authorisation. Balance US$2.55bn at 28 June 2026. (2) STRC dividend policy: rate evaluated monthly against trading levels, yields, spreads, bitcoin price and volatility, reserve coverage and capital structure; not raised merely because STRC trades below its stated amount. (3) Preferred repurchase program, up to US$1.0bn across STRC, STRF, STRD and STRK, STRC first; never funded from the USD Reserve. (4) Common stock repurchase program, up to US$1.0bn; never funded from the USD Reserve. (5) BTC Monetization Program: bitcoin may be sold for three purposes only — up to US$1.25bn to fund the USD Reserve; paying dividends and interest when management judges it more advantageous than issuing common stock; and funding the two repurchase programs. Anything outside those purposes or limits needs further board authorisation. No expiry; no obligation to sell.',
  'sec',
  'Strategy Inc',
